function boardEvents(raw,date,shift){const ev=[];rowsArray(raw?.rows).forEach((r,ri)=>{if(!r)return;turnArray(r.turns).forEach((t,ti)=>{if(!t||t.skipped||!t.table)return;const p=Math.max(0,parseInt(t.people)||0),ts=epoch(t.entryId||t.partyId);ev.push({source:'LIVE',date,shift,server:canonical(r.server||'Unknown'),rawServer:normName(r.server||'Unknown'),section:txt(r.section),table:txt(t.table),people:p,rotationSlots:Math.max(1,Math.ceil(Math.max(1,p)/4)),seatedAt:ts,row:ri,turn:ti})})});return ev}
function archiveEvents(snap,date,shift){const arr=Array.isArray(snap?.events)?snap.events:Object.values(snap?.events||{});return arr.filter(Boolean).map(e=>({...e,date:e.date||date,shift:e.shift||shift,source:'ARCHIVE',server:canonical(e.server),rawServer:normName(e.server),people:num(e.people),rotationSlots:Math.max(1,num(e.rotationSlots)||Math.ceil(Math.max(1,num(e.people))/4))}))}
function boardRosterFromBoard(raw,date,shift){const out=[];rowsArray(raw?.rows).forEach((r,ri)=>{if(!r||!normName(r.server)||r.active===false||r.cutAt)return;out.push({date,shift,server:canonical(r.server),rawServer:normName(r.server),section:txt(r.section),workShift:txt(r.workShift||shift),row:ri,source:'BOARD LIVE'})});return out}
function teamShiftPeriods(v){const s=txt(v).toUpperCase();if(s.includes('DOUBLE'))return ['AM','PM'];if(s==='AM'||(s.includes('10:45')&&s.includes('2')))return ['AM'];if(s==='PM'||s.includes('LONG')||s.includes('2 PM')||s.includes('2–4')||s.includes('2-4'))return ['PM'];return ['AM','PM']}
