function pdfText(d,text,x,y,maxW,fontSize=9,color=[45,68,88],style='normal'){d.setFont('helvetica',style);d.setFontSize(fontSize);d.setTextColor(...color);const lines=d.splitTextToSize(txt(text),maxW);d.text(lines,x,y);return y+lines.length*(fontSize*1.18)}
function pdfCard(d,x,y,w,h,title,value,sub,color=[28,194,220]){d.setFillColor(205,225,238);d.roundedRect(x+5,y+7,w,h,14,14,'F');d.setFillColor(255,255,255);d.setDrawColor(205,226,238);d.roundedRect(x,y,w,h,14,14,'FD');d.setFillColor(...color);d.roundedRect(x,y,6,h,4,4,'F');pdfText(d,title,x+15,y+19,w-25,7,[93,118,138],'bold');pdfText(d,value,x+15,y+42,w-25,18,[20,49,72],'bold');if(sub)pdfText(d,sub,x+15,y+h-12,w-25,6.8,[104,126,143],'normal')}
function pdfHeader(d,L,pageTitle,page){d.setFillColor(246,252,255);d.rect(0,0,792,612,'F');d.setFillColor(21,199,223);d.roundedRect(0,0,792,9,0,0,'F');d.setFillColor(62,124,244);d.roundedRect(210,0,350,9,0,0,'F');d.setFillColor(139,99,246);d.roundedRect(520,0,272,9,0,0,'F');pdfText(d,'FZ SERVER INTELLIGENCE V1.2',30,38,350,15,[19,55,83],'bold');pdfText(d,pageTitle,30,60,520,11,[74,91,112],'bold');pdfText(d,`${L.period}: ${state.from} → ${state.to} • ${state.shift}`,30,78,500,8,[108,128,145]);pdfText(d,`Page ${page}/3`,710,38,55,8,[108,128,145],'bold')}
function draw3DBarChart(d,x,y,w,h,items,title,valueFn=v=>Math.round(v)){pdfText(d,title,x,y+12,w,9,[35,66,93],'bold');const data=items.slice(0,6),max=Math.max(1,...data.map(a=>num(a.value))),barY=y+28,rowH=(h-35)/Math.max(1,data.length);data.forEach((it,i)=>{const yy=barY+i*rowH,bw=(w-145)*num(it.value)/max;pdfText(d,(i+1)+'. '+it.name,x,yy+9,125,7.2,[55,78,98],'bold');d.setFillColor(219,231,240);d.roundedRect(x+130,yy+3,w-170,11,5,5,'F');d.setFillColor(150,111,235);d.roundedRect(x+133,yy+6,bw,11,5,5,'F');d.setFillColor(42,194,223);d.roundedRect(x+130,yy+3,bw,10,5,5,'F');d.setFillColor(255,255,255);if(bw>24)d.roundedRect(x+134,yy+5,Math.min(24,bw-5),2,1,1,'F');pdfText(d,valueFn(it.value),x+w-35,yy+11,32,7,[31,62,86],'bold')})}
function pdfBulletList(d,items,x,y,w,{font=8,color=[55,77,96],bullet=[59,124,244],limit=5}={}){let yy=y;for(const item of items.slice(0,limit)){d.setFillColor(...bullet);d.circle(x+4,yy-2,2.2,'F');yy=pdfText(d,item,x+12,yy,w-12,font,color,'normal')+5}return yy}
